//! The example configurations in `docs/examples` are generated by the programs in
//! `crates/ssk-config/examples`, and these tests fail when a file differs from its
//! generator's output, so an example cannot rot behind a schema change. Each
//! generator lints its own output; here the checked-in file is also read the way
//! the daemon reads it.
//!
//! Regenerate with the command named in the failure message.

use ssk_config::ingress::{DirectAddressFamilies, IngressHardening};
use ssk_config::routing::RoutingAction;
use ssk_config::{AppConfig, ConfigFormat, CURRENT_CONFIG_VERSION};
use std::path::PathBuf;

// The generators are `include!`d rather than run: a test that shelled out to
// `cargo run` would nest a build, and `cargo test` does not build examples when a
// single test target is named.
#[allow(dead_code)]
mod ingress_example {
    include!("../examples/ingress_config.rs");
}

#[allow(dead_code)]
mod coexistence_example {
    include!("../examples/coexistence_config.rs");
}

fn checked_in(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../docs/examples")
        .join(name);
    std::fs::read_to_string(&path)
        .unwrap_or_else(|err| panic!("{}: {err}", path.display()))
        // A checkout that converts line endings must not read as drift.
        .replace("\r\n", "\n")
}

fn assert_current(name: &str, example: &str, generated: &str) {
    let pinned = checked_in(name);
    if pinned != generated {
        let (line, (was, is)) = pinned
            .lines()
            .zip(generated.lines())
            .enumerate()
            .find(|(_, (was, is))| was != is)
            .map_or((pinned.lines().count(), ("<end>", "<end>")), |(i, pair)| {
                (i, pair)
            });
        panic!(
            "docs/examples/{name} differs from its generator at line {}:\n  checked in: {was}\n  \
             generated:  {is}\nregenerate: cargo run -q -p ssk-config --example {example} > \
             docs/examples/{name}",
            line + 1
        );
    }
}

/// What the daemon does with the file: read it through the migration path, as the
/// current version, and validate it.
fn loaded(name: &str) -> AppConfig {
    let text = checked_in(name);
    let loaded = AppConfig::parse_with_migration_yaml(&text)
        .unwrap_or_else(|err| panic!("docs/examples/{name} does not load: {err}"));
    assert_eq!(
        loaded.migrated_from, None,
        "{name} is not a current-version file"
    );
    assert_eq!(loaded.config.version, CURRENT_CONFIG_VERSION);
    assert!(loaded.config.validate().is_ok());
    assert!(ssk_config::lint(&text, ConfigFormat::Yaml).ok);
    loaded.config
}

#[test]
fn ingress_example_is_current() {
    assert_current(
        "ingress.example.yaml",
        "ingress_config",
        &ingress_example::document().expect("the generator lints its own output"),
    );
}

#[test]
fn ingress_example_validates() {
    let config = loaded("ingress.example.yaml");
    // Enabled, and otherwise the defaults: the file is the one place an operator
    // sees every key.
    assert!(config.ingress.enabled);
    let mut expected = AppConfig::default().ingress;
    expected.enabled = true;
    assert_eq!(config.ingress, expected);
    assert!(config
        .routing
        .profiles
        .iter()
        .all(|profile| profile.rules.is_empty()));
}

#[test]
fn coexistence_example_is_current() {
    assert_current(
        "ingress-coexistence.yaml",
        "coexistence_config",
        &coexistence_example::document().expect("the generator lints its own output"),
    );
}

#[test]
fn coexistence_example_validates() {
    let config = loaded("ingress-coexistence.yaml");
    assert!(config.ingress.enabled);
    assert!(
        !config.ingress.arm_on_start,
        "armed on start would not be the scenario"
    );
    assert_eq!(config.ingress.hardening, IngressHardening::BestEffort);
    assert_eq!(
        config.ingress.direct_address_families,
        DirectAddressFamilies::Ipv4Only
    );
    assert_eq!(config.routing.default_profile, "coexist");
    assert!(
        config.routing.adapters.is_empty(),
        "Direct only: no adapter"
    );
    let profile = &config.routing.profiles[0];
    let ids: Vec<&str> = profile.rules.iter().map(|rule| rule.id.as_str()).collect();
    assert_eq!(
        ids,
        [
            "deny-blocked-example",
            "echo-ipify",
            "echo-ipify-dual",
            "echo-ipify-v6",
            "allow-rest-443",
            "allow-rest-80"
        ]
    );
    // Only the deny rule is not a Direct one: nothing here leaves through a proxy.
    let direct = profile
        .rules
        .iter()
        .filter(|rule| matches!(rule.action, RoutingAction::Direct))
        .count();
    assert_eq!(direct, 5);
}
